ROOT = r"C:\Проекты VS\C проги и пай клиенты\test1\test"
sys.path.insert(0, ROOT)
from m8051.rom import ROM
from tools.disasm import disassemble_one
rom = ROM().load_file(ROOT + r"\firmware\nm27c512n.hex")
img = bytes(rom.byte(0x8000 + i) for i in range(0x8000))

def find(pat):
    out, i = [], 0
    while True:
        i = img.find(pat, i)
        if i < 0: return out
        out.append(0x8000 + i); i += 1

# direct-RAM writes to 0x38..0x3D  (MOV direct,A = F5 dd)
print("### MOV 38h..3Dh,A  (F5 xx)")
for d in range(0x38, 0x3E):
    for a in find(bytes([0xF5, d])):
        print(f"   {a:04X}: MOV {d:02X}h,A")
print("### MOV 38h..3Dh,#imm (75 xx)")
for d in range(0x38, 0x3E):
    for a in find(bytes([0x75, d])):
        print(f"   {a:04X}: MOV {d:02X}h,#{img[a-0x8000+2]:02X}h")
print("### MOV R0,#38h (78 38) / MOV R1,#38h")
for a in find(bytes([0x78, 0x38])) + find(bytes([0x79, 0x38])):
    print(f"   {a:04X}")
print("### MOV @R0,A (F6) sites count", len(find(bytes([0xF6]))))
print("### MOVX read sites with DPH=0x91")
for a in find(bytes([0x75, 0x83, 0x91])):
    print(f"   DPH=91 at {a:04X}")
